CREATE OR REPLACE FUNCTION calculate_lssr(p_equip_code text)
RETURNS numeric AS $$
DECLARE
    v_oper_hours real;
    v_maint_cycle real;
    v_status text;
    v_ors numeric;
    v_insulation_stat text;
    v_heat_loss real;
    v_tie numeric;
    v_lssr numeric;
BEGIN
    -- Get operational data from OperationMaintenance joined with CabinEnvironment
    SELECT om."OPER_hours", om."maintCycleHrs", ce.cabin_env_snapshot->>'emergency'
    INTO v_oper_hours, v_maint_cycle, v_status
    FROM "OperationMaintenance" om
    JOIN "CabinEnvironment" ce ON om."equipRef" = ce."equipRef"
    WHERE om."equipRef" = p_equip_code
    LIMIT 1;

    -- Calculate ORS
    IF v_status = 'Active' THEN
        IF v_maint_cycle IS NOT NULL AND v_maint_cycle > 0 THEN
            v_ors := 10 * (1 - COALESCE(v_oper_hours, 0) / v_maint_cycle);
        ELSE
            v_ors := 0;
        END IF;
    ELSIF v_status = 'Standby' THEN
        IF v_maint_cycle IS NOT NULL AND v_maint_cycle > 0 THEN
            v_ors := 5 * (1 - COALESCE(v_oper_hours, 0) / v_maint_cycle);
        ELSE
            v_ors := 0;
        END IF;
    ELSE
        v_ors := 0;
    END IF;

    -- TIE: Since ThermalSolarWindAndGrid doesn't have equipRef, we check via loc_link through location
    -- For life support (Shelter), we use the first available thermal record or NULL
    SELECT t."insulationStat", t."heatLoss_kwh"
    INTO v_insulation_stat, v_heat_loss
    FROM "ThermalSolarWindAndGrid" t
    LEFT JOIN "Communication" c ON t."comm_link" = c."COMM_ID"
    LEFT JOIN "CabinEnvironment" ce2 ON c."COMM_ID" = ce2."comm_link"
    WHERE ce2."equipRef" = p_equip_code
    LIMIT 1;

    -- Calculate TIE
    IF v_insulation_stat = 'Good' THEN
        v_tie := 0.9 - COALESCE(v_heat_loss, 0) / 10.0;
    ELSIF v_insulation_stat = 'Fair' THEN
        v_tie := 0.6 - COALESCE(v_heat_loss, 0) / 10.0;
    ELSIF v_insulation_stat = 'Poor' THEN
        v_tie := 0.3 - COALESCE(v_heat_loss, 0) / 10.0;
    ELSE
        v_tie := 0;
    END IF;

    -- Calculate LSSR
    v_lssr := 0.7 * COALESCE(v_ors, 0) + 0.3 * COALESCE(v_tie, 0);

    RETURN ROUND(CAST(v_lssr AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

